+package invoices
+
+import (
+	"context"
+	"fmt"
+	"time"
+
+	"golang.org/x/sync/errgroup"
+)
+
+const graceDays = 14
+
+// Overdue returns the open invoices of a customer that are past their grace period.
+func (s *Service) Overdue(ctx context.Context, customerID string) ([]Invoice, error) {
+	invs, err := s.repo.ListOpen(ctx, customerID)
+	if err != nil {
+		return nil, fmt.Errorf("list open invoices for %s: %w", customerID, err)
+	}
+	var out []Invoice
+	for _, inv := range invs {
+		if isPastGrace(inv) {
+			out = append(out, inv)
+		}
+	}
+	return out, nil
+}
+
+func isPastGrace(inv Invoice) bool {
+	deadline := inv.DueDate.Add(graceDays * 24 * time.Hour)
+	return time.Now().After(deadline)
+}
+
+// SendReminders emails every customer in the batch that has overdue invoices, at most 8 at a time.
+func (s *Service) SendReminders(ctx context.Context, customerIDs []string) error {
+	g, ctx := errgroup.WithContext(ctx)
+	g.SetLimit(8)
+	for _, id := range customerIDs {
+		id := id
+		g.Go(func() error {
+			overdue, err := s.Overdue(ctx, id)
+			if err != nil {
+				return fmt.Errorf("reminders for %s: %w", id, err)
+			}
+			if len(overdue) == 0 {
+				return nil
+			}
+			if err := s.mailer.SendReminder(ctx, id, overdue); err != nil {
+				return fmt.Errorf("send reminder to %s: %w", id, err)
+			}
+			// metrics are best-effort; a failed increment must not fail the batch
+			_ = s.metrics.Inc(ctx, "reminders_sent")
+			s.log.Info("reminder sent", "customer_id", id, "invoices", len(overdue), "sent_at", s.clock.Now())
+			return nil
+		})
+	}
+	if err := g.Wait(); err != nil {
+		return fmt.Errorf("send reminders: %w", err)
+	}
+	s.log.Info("reminder batch done", "customers", len(customerIDs))
+	return nil
+}
